param([Parameter(Mandatory=$true)][string]$RunPath,[string]$Stage1ReportPath='')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$repo=$PSScriptRoot;while(-not [IO.File]::Exists((Join-Path $repo 'bootstrap/tools/verification.ps1'))){$parent=Split-Path $repo -Parent;if(-not $parent -or $parent -eq $repo){throw 'Repository root not found'};$repo=$parent};. (Join-Path $repo 'bootstrap/tools/verification.ps1');. (Join-Path $repo 'compiler/UBE_Compiler_v3/tests/semantic/native/abi.ps1')
$previous=[IO.File]::ReadAllText((Join-Path $RunPath 'report.json'))|ConvertFrom-Json
$mapping=[pscustomobject]@{procedures=@{};types=@{}};foreach($p in $previous.mapping.procedures.PSObject.Properties){$mapping.procedures[$p.Name]=$p.Value};foreach($p in $previous.mapping.types.PSObject.Properties){$mapping.types[$p.Name]=$p.Value}
$originalLLVM=Join-Path $RunPath 'whole-native.ll';$stageEvidence=$null
if($Stage1ReportPath -ne ''){$stage=[IO.File]::ReadAllText($Stage1ReportPath)|ConvertFrom-Json;if(-not $stage.success -or -not $stage.rawStageIdentity -or $stage.firstStageReport.sha256 -cne (Get-ArtifactIdentity (Join-Path $RunPath 'report.json')).sha256){throw 'Matching successful preserved stage1 report required'};$originalLLVM=Join-Path (Split-Path $Stage1ReportPath -Parent) 'whole-native.ll';$stageEvidence=Get-ArtifactIdentity $Stage1ReportPath}
$target=Join-Path $RunPath ('overlap-'+$(if($Stage1ReportPath -ne ''){'stage1-'}else{''})+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($target);$utf8=New-Object Text.UTF8Encoding($false)
foreach($file in @('overlap-probe.c','targeted-probe.c','probe.c','scalar-complete.h','overlap-check.ps1')){Copy-Item -LiteralPath (Join-Path $PSScriptRoot $file) -Destination $target};Copy-Item -LiteralPath (Join-Path $RunPath 'scalar-source.h') -Destination $target
$projectLines=@('UBE-Project 1','Name = "SemanticOverlapFixture"','Kind = "Exe"','Startup = "Main"');for($i=0;$i -lt 4;$i++){$procedure=if($i -eq 0){'Main'}else{'Work'+$i};$source="UBE SOURCE 1 MODULE`nAttribute UBE_Name = ""Module$i""`nSub $procedure()`nDim x As Long = $($i+1)&`nEnd Sub`n";[IO.File]::WriteAllText((Join-Path $target "Module$i.bas"),$source,$utf8);$projectLines+='Source = "Module'+$i+'.bas"'};$project=Join-Path $target 'App.UBE';[IO.File]::WriteAllText($project,($projectLines -join "`n")+"`n",$utf8)
$raw=[IO.File]::ReadAllText($originalLLVM);$adapter=New-Object Text.StringBuilder
$body='ptr, ptr, ptr, '+$mapping.types.SemanticLimits+', i32, i32, ptr, i32, ptr, i32, i32, i32, '+$mapping.types.SemanticFailure+', '+$mapping.types.SemanticFailure+', '+$mapping.types.SemanticMetrics+', ptr, i64, i32';$null=Assert-FoundationRecord $raw $mapping 'SemanticModuleWork' $body
$null=Get-FoundationDefinition $raw $mapping 'ProcessSemanticModule' 'void' 'ptr,ptr'
Add-FoundationBinding $adapter $raw $mapping 'statement_bind' 'TryBindSemanticModule' 'i1' 'ptr'
[void]$adapter.AppendLine("declare i32 @whole_semantic_worker(ptr)`ndefine i1 @overlap_bind_bridge(ptr %work) {`n %status = call i32 @whole_semantic_worker(ptr %work)`n %accepted = icmp ne i32 %status, 0`n ret i1 %accepted`n}")
$call='call i1 @'+$mapping.procedures.TryBindSemanticModule+'(';if(([regex]::Matches($raw,[regex]::Escape($call))).Count -ne 1){throw 'Exactly one actual admitted semantic worker binder call required'}
$ir=Join-Path $target 'whole-native.ll';[IO.File]::WriteAllText($ir,$raw.Replace($call,'call i1 @overlap_bind_bridge(')+"`n"+$adapter.ToString(),$utf8)
$records=@();$commands=@();$success=$false;$failure=$null
try{
 foreach($variant in @('positive','negative')){$exe=Join-Path $target ($variant+'.exe');$arguments=@('--target=x86_64-w64-windows-gnu','-O2','-I',$target,'-I',(Join-Path $repo 'bootstrap/runtime'),'-x','ir',$ir,'-x','c',(Join-Path $target 'overlap-probe.c'),'-std=c11','-Wall','-Wextra','-Werror');if($variant -eq 'negative'){$arguments+='-DOVERLAP_NEGATIVE_CAPTURE'};$arguments+=@('-x','none',(Join-Path $RunPath 'runtime-whole.o'),$previous.selection.unicodeRuntime.path,'-o',$exe);$link=Invoke-BoundedProcess $previous.selection.clang.path $arguments $repo 120;$commands+=@($link);if($link.timedOut -or $link.exit -ne 0){throw $link.stderr}
  $jobs=if($variant -eq 'positive'){@(1,2,4)}else{@(4)};$baseline=$null
  foreach($job in $jobs){$run=Invoke-BoundedProcess $exe @('--project',[IO.Path]::GetFullPath($project),[string]$job) $repo 60;$commands+=@($run);if($variant -eq 'positive'){if($run.timedOut -or $run.exit -ne 0 -or $run.stderr -cne ''){throw "Native overlap failed: $($run.stderr)"};$lines=@($run.stdout.Trim().Split("`n"));$actual=$lines[-1]|ConvertFrom-Json;if(-not $actual.passed -or $actual.actualPeakWorkers -ne $job -or $actual.completed -ne 4){throw 'Wrong overlap scalar observations'};if($null -eq $baseline){$baseline=$lines[0]}elseif($baseline -cne $lines[0]){throw 'Complete semantic scalar stream changed across worker budgets'}}elseif($run.timedOut -or $run.exit -ne 1 -or -not $run.stderr.Contains('atomic_load(&bad)==0')){throw 'Wrong capture/source expectation control was not rejected'};$records+=@([pscustomobject]@{variant=$variant;jobs=$job;run=$run})}
 };$success=$true
}catch{$failure=$_.Exception.Message}
[pscustomobject]@{success=$success;qualified=$false;diagnosticOnly=$true;failure=$failure;originalReport=(Get-ArtifactIdentity (Join-Path $RunPath 'report.json'));stage1Report=$stageEvidence;originalLLVM=(Get-ArtifactIdentity $originalLLVM);staticCallSites=1;records=$records;commands=$commands;artifacts=@(Get-ChildItem -LiteralPath $target -File|ForEach-Object{Get-ArtifactIdentity $_.FullName});limits='Actual unchanged static UBE ProcessSemanticModule worker/capture path with a bounded scalar observer barrier after admission. Four-source functional payload and full-stream identity at jobs1/2/4; exact4-worker overlap at jobs4. Actual capture32bytes, sourcecopies/resizes0 and native allocation/copy/root/heap counters. Wrong captured source expectation rejected. No exhaustive start/wait/storage/cancel/root-pressure qualification.'}|ConvertTo-Json -Depth 20|Set-Content -LiteralPath (Join-Path $target 'report.json') -Encoding UTF8
Write-Output "Evidence: $target/report.json";if(-not $success){throw $failure}
